const segment = $('3. Split Segments').item.json;
const cohortResponse = $json;
const cohort = Array.isArray(cohortResponse.data) ? cohortResponse.data : [];
const segmentId = segment.id;
if (!segmentId || !segment.criteria) {
  throw new Error('Segment ID or criteria is missing');
}
const baseUrl = $env.CRM_API_BASE_URL;
const apiKey = $env.N8N_API_KEY;
const executionId = String($execution.id || '');
if (!baseUrl || !apiKey || !executionId) {
  throw new Error('CRM_API_BASE_URL, N8N_API_KEY, and execution ID are required');
}
const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: baseUrl.replace(/\/$/, '') + '/internal/n8n/segments/' + segmentId + '/workflow-runs',
  headers: { 'X-N8N-API-KEY': apiKey, 'Idempotency-Key': executionId + ':' + segmentId, 'Content-Type': 'application/json' },
  body: {},
  json: true
});
if (!resp.workflowRunId) {
  throw new Error('Backend did not return a workflowRunId');
}
return {
  json: {
    segmentId,
    segmentName: segment.name,
    criteria: segment.criteria,
    isActive: segment.isActive,
    cohortSize: cohort.length,
    workflowRunId: resp.workflowRunId,
    validatedAt: new Date().toISOString()
  }
};

const resp = $json;
const stats = {
  status: resp.status || 'UNKNOWN',
  total: resp.total ?? null,
  processed: resp.processed ?? null,
  matched: resp.matched ?? null,
  message: resp.message || '',
  source: 'backend_rule_engine',
  retrievedAt: new Date().toISOString()
};
if (stats.total === null || stats.processed === null || stats.matched === null) {
  throw new Error('Missing required statistics from backend response');
}
return { json: stats };

const stats = $json;
const segment = $('5. Validate Evaluation Request').item.json;
return {
  json: {
    segmentId: segment.segmentId,
    segmentName: segment.segmentName,
    workflowRunId: segment.workflowRunId,
    status: stats.status,
    total: stats.total,
    processed: stats.processed,
    matched: stats.matched,
    unmatched: stats.total - stats.matched,
    matchRate: stats.total > 0 ? (stats.matched / stats.total * 100).toFixed(2) + '%' : '0%',
    message: stats.message
  }
};

const input = $('8. Normalize Statistics').item.json;
const aiResponse = $json;
let rawText = '';
if (typeof aiResponse === 'string') rawText = aiResponse;
else if (aiResponse && aiResponse.text) rawText = aiResponse.text;
else if (aiResponse && aiResponse.content) rawText = aiResponse.content;
else rawText = JSON.stringify(aiResponse);
rawText = rawText.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
let insights = [];
try {
  const parsed = JSON.parse(rawText);
  insights = Array.isArray(parsed) ? parsed : (parsed.insights || []);
} catch {
  insights = [];
}
const evidenceValues = new Map(Object.entries(input).filter(([key]) => ['total', 'processed', 'matched', 'unmatched', 'matchRate'].includes(key)).map(([key, value]) => [key, String(value)]));
const validInsights = insights.filter(ins => {
  if (!ins || typeof ins !== 'object' || typeof ins.insight !== 'string' || !ins.insight.trim()) return false;
  if (typeof ins.evidence !== 'string' || typeof ins.confidence !== 'number' || ins.confidence < 0 || ins.confidence > 1) return false;
  const [field, ...valueParts] = ins.evidence.split('=');
  return evidenceValues.has(field) && valueParts.join('=') === evidenceValues.get(field);
});
return {
  json: {
    segmentId: input.segmentId,
    segmentName: input.segmentName,
    workflowRunId: input.workflowRunId,
    total: input.total,
    processed: input.processed,
    matched: input.matched,
    unmatched: input.unmatched,
    matchRate: input.matchRate,
    aiInsights: validInsights,
    rejectedInsights: insights.length - validInsights.length,
    validatedAt: new Date().toISOString()
  }
};
